B.NG={press_banca:0,press_inclinado_mancuerna:1,aperturas_polea:2,fondos:3,dominadas:4,remo_barra:5,jalon_polea:6,remo_mancuerna:7,peso_muerto:8,press_militar:9,elevaciones_laterales:10,pajaro:11,curl_barra:12,curl_martillo:13,extension_triceps_polea:14,press_frances:15,curl_muneca:16,sentadilla:17,prensa:18,zancadas:19,curl_femoral:20,elevacion_talones:21,plancha:22,elevacion_piernas:23,rueda_abdominal:24,flexiones:25,flexiones_diamante:26,sentadilla_goblet:27,sentadilla_libre:28,peso_muerto_rumano:29,press_hombro_mancuerna:30,curl_mancuerna:31,extension_triceps_mancuerna:32,remo_banda:33,puente_gluteo:34,talones_libre:35,crunch:36,flexiones_rodillas:37,flexiones_inclinadas:38,flexiones_declinadas:39,remo_mesa:40,superman:41,remo_garrafa:42,flexiones_pica:43,press_banda:44,elevaciones_botellas:45,curl_banda:46,curl_garrafa:47,fondos_silla:48,curl_muneca_garrafa:49,paseo_granjero:50,escaladores:51,tijeras:52,zancada_atras:53,sentadilla_bulgara:54,sentadilla_pared:55,subida_escalon:56,sentadilla_salto:57,puente_una_pierna:58,talones_una_pierna:59,saltitos:60,saltos_tijera:61}
B.aBj=s(["T\xfambate con los ojos bajo la barra y los pies firmes en el suelo.","Junta las esc\xe1pulas y agarra un poco m\xe1s ancho que los hombros.","Baja controlado hasta rozar el pecho, a la altura del estern\xf3n.","Empuja hacia arriba y un poco hacia atr\xe1s hasta estirar los brazos."],t.s)
B.awH=s(["Rebotar la barra en el pecho.","Despegar la cadera del banco."],t.s)
B.amU=new A.co(B.aBj,B.awH,"Suelta el aire al subir o empujar.")
B.ayt=s(["Banco a 30\u201345\xb0. Mancuernas a la altura del pecho alto.","Codos a unos 45\xb0 del cuerpo, no abiertos en cruz.","Empuja hasta casi juntar las mancuernas arriba.","Baja lento hasta sentir el estiramiento del pecho."],t.s)
B.axA=s(["Inclinar demasiado el banco (trabaja m\xe1s el hombro)."],t.s)
B.anE=new A.co(B.ayt,B.axA,"Suelta el aire al subir o empujar.")
B.awA=s(["Poleas altas, un pie adelantado y el pecho erguido.","Codos ligeramente doblados durante todo el recorrido.","Cierra los brazos en arco hasta juntar las manos delante.","Vuelve despacio hasta sentir el pecho estirado."],t.s)
B.atm=s(["Convertirlo en un press doblando los codos."],t.s)
B.anB=new A.co(B.awA,B.atm,"Suelta el aire al subir o empujar.")
B.aFC=s(["Sube a las paralelas con los brazos estirados y hombros abajo.","Inclina un poco el torso hacia delante.","Baja hasta que los codos lleguen a unos 90\xb0.","Empuja hasta estirar los brazos sin bloquear de golpe."],t.s)
B.axr=s(["Bajar demasiado si te molesta el hombro.","Encoger los hombros hacia las orejas."],t.s)
B.anz=new A.co(B.aFC,B.axr,"Suelta el aire al subir o empujar.")
B.aE6=s(["Cu\xe9lgate con agarre algo m\xe1s ancho que los hombros.","Baja los hombros y aprieta el abdomen antes de tirar.","Tira llevando los codos hacia las costillas hasta pasar la barbilla.","Baja completo y controlado, sin soltarte de golpe."],t.s)
B.auR=s(["Balancearse para ayudarse.","Hacer medias repeticiones."],t.s)
B.an3=new A.co(B.aE6,B.auR,"Suelta el aire al subir.")
B.aDi=s(["Rodillas un poco flexionadas, torso inclinado unos 45\xb0 y espalda recta.","La barra cuelga bajo los hombros.","Tira hacia el ombligo llevando los codos atr\xe1s.","Aprieta la espalda arriba un instante y baja controlado."],t.s)
B.azV=s(["Redondear la espalda.","Levantar el torso para tirar."],t.s)
B.ank=new A.co(B.aDi,B.azV,"Suelta el aire al subir o empujar.")
B.auV=s(["Si\xe9ntate con los muslos fijos bajo el apoyo.","Agarra ancho y saca un poco el pecho.","Tira de la barra hacia la parte alta del pecho.","Sube despacio hasta estirar los brazos."],t.s)
B.aFk=s(["Tirar detr\xe1s de la nuca.","Echarse muy atr\xe1s para mover m\xe1s peso."],t.s)
B.anr=new A.co(B.auV,B.aFk,"Suelta el aire al subir o empujar.")
B.azz=s(["Apoya una mano y una rodilla en el banco, espalda plana.","La mancuerna cuelga bajo el hombro.","Tira llevando el codo hacia la cadera.","Baja hasta estirar el brazo por completo."],t.s)
B.avW=s(["Girar el torso para subir m\xe1s."],t.s)
B.anM=new A.co(B.azz,B.avW,"Suelta el aire al subir o empujar.")
B.aAk=s(["Barra sobre la mitad del pie, espinillas casi toc\xe1ndola.","Cadera atr\xe1s, espalda recta y pecho arriba al agarrar.","Empuja el suelo con las piernas: la barra sube pegada al cuerpo.","Termina erguido, apretando gl\xfateos, sin echarte atr\xe1s."],t.s)
B.auh=s(["Redondear la espalda baja.","Alejar la barra del cuerpo."],t.s)
B.anI=new A.co(B.aAk,B.auh,"Suelta el aire al subir o empujar.")
B.aEZ=s(["De pie, barra a la altura de las clav\xedculas, abdomen y gl\xfateos firmes.","Empuja recto hacia arriba apartando un poco la cabeza.","Arriba, mete la cabeza entre los brazos.","Baja controlado hasta las clav\xedculas."],t.s)
B.aCG=s(["Arquear la espalda baja.","Empujar la barra hacia delante."],t.s)
B.anF=new A.co(B.aEZ,B.aCG,"Suelta el aire al subir o empujar.")
B.ath=s(["De pie, mancuernas a los lados y codos un poco doblados.",u.Y,"Imagina que empujas las paredes, no que subes las manos.","Baja lento, sin dejarlas caer."],t.s)
B.awD=s(["Balancear el cuerpo.","Subir los hombros hacia las orejas."],t.s)
B.an_=new A.co(B.ath,B.awD,"Suelta el aire al subir o empujar.")
B.atl=s(["Inclina el torso casi paralelo al suelo con la espalda recta.","Mancuernas colgando, codos un poco doblados.","Abre los brazos hacia los lados apretando la parte de atr\xe1s del hombro.","Baja controlado."],t.s)
B.aBl=s(["Juntar las esc\xe1pulas en vez de mover los brazos."],t.s)
B.anm=new A.co(B.atl,B.aBl,"Suelta el aire al subir o empujar.")
B.aB6=s(["De pie, barra con agarre a la anchura de los hombros.","Codos pegados al cuerpo y quietos.","Sube la barra doblando solo los codos.","Baja hasta estirar casi del todo."],t.s)
B.aDE=s(["Balancear el torso.","Adelantar los codos."],t.s)
B.an6=new A.co(B.aB6,B.aDE,"Suelta el aire al subir o empujar.")
B.ayK=s(["Mancuernas con las palmas mir\xe1ndose, como un martillo.","Codos fijos a los lados.","Sube sin girar la mu\xf1eca.","Baja lento."],t.s)
B.aDh=s(["Ayudarse con el hombro."],t.s)
B.anq=new A.co(B.ayK,B.aDh,"Suelta el aire al subir o empujar.")
B.azY=s(["Frente a la polea alta, codos pegados a las costillas.","Empuja hacia abajo hasta estirar los brazos.","Aprieta el tr\xedceps abajo un instante.","Sube solo hasta que el antebrazo quede horizontal."],t.s)
B.au9=s(["Separar los codos del cuerpo.","Usar el peso del cuerpo."],t.s)
B.and=new A.co(B.azY,B.au9,"Suelta el aire al subir o empujar.")
B.aFH=s(["Tumbado, barra sobre la frente con los brazos verticales.","Baja doblando solo los codos hacia la frente o detr\xe1s de la cabeza.","Los codos apuntan al techo todo el tiempo.","Extiende hasta estirar los brazos."],t.s)
B.aEU=s(["Abrir los codos hacia los lados."],t.s)
B.ann=new A.co(B.aFH,B.aEU,"Suelta el aire al subir o empujar.")
B.aFv=s(["Sentado, antebrazos sobre los muslos y mu\xf1ecas por fuera de las rodillas.","Deja que la barra baje hasta los dedos.","Sube doblando solo la mu\xf1eca.","Movimientos cortos y controlados."],t.s)
B.aEQ=s(["Mover los antebrazos."],t.s)
B.anf=new A.co(B.aFv,B.aEQ,"Suelta el aire al subir o empujar.")
B.axl=s(["Barra sobre la parte alta de la espalda, pies a la anchura de los hombros.","Inspira, aprieta el abdomen y lleva la cadera atr\xe1s y abajo.","Rodillas en la direcci\xf3n de las puntas de los pies.","Baja hasta que el muslo quede paralelo o m\xe1s, y sube empujando el suelo."],t.s)
B.axe=s(["Rodillas hacia dentro.","Levantar los talones.","Redondear la espalda abajo."],t.s)
B.an4=new A.co(B.axl,B.axe,"Suelta el aire al subir o empujar.")
B.aF9=s(["Espalda y cadera pegadas al respaldo.","Pies en el centro de la plataforma, a la anchura de la cadera.","Baja hasta que las rodillas lleguen a unos 90\xb0.","Empuja sin bloquear las rodillas al final."],t.s)
B.azW=s(["Despegar la cadera abajo.","Bloquear las rodillas de golpe."],t.s)
B.anl=new A.co(B.aF9,B.azW,"Suelta el aire al subir o empujar.")
B.aBF=s(["De pie con las mancuernas a los lados.","Da un paso largo adelante.",u.B,"Empuja con el pie de delante para volver."],t.s)
B.aC3=s(["Paso demasiado corto (la rodilla se pasa mucho)."],t.s)
B.anA=new A.co(B.aBF,B.aC3,"Suelta el aire al subir o empujar.")
B.ayF=s(["Tumbado boca abajo, el rodillo justo encima de los talones.","Cadera pegada al banco.","Lleva los talones hacia los gl\xfateos.","Baja despacio sin dejar caer el peso."],t.s)
B.aCX=s(["Levantar la cadera para subir."],t.s)
B.an8=new A.co(B.ayF,B.aCX,"Suelta el aire al subir o empujar.")
B.aCF=s(["Puntas de los pies en el borde, talones en el aire.","Baja los talones hasta sentir el estiramiento.","Sube todo lo posible sobre las puntas.","Mant\xe9n un segundo arriba."],t.s)
B.aEG=s(["Rebotar abajo.","Doblar las rodillas."],t.s)
B.amZ=new A.co(B.aCF,B.aEG,"Suelta el aire al subir o empujar.")
B.aBp=s(["Manos (o antebrazos) bajo los hombros, cuerpo en l\xednea recta.","Aprieta abdomen y gl\xfateos.","No dejes caer ni subir la cadera.","Respira normal y aguanta el tiempo marcado."],t.s)
B.atT=s(["Hundir la zona lumbar."],t.s)
B.anC=new A.co(B.aBp,B.atT,"Respira corto y constante; no aguantes el aire.")
B.aBO=s(["Tumbado boca arriba, manos a los lados o bajo la cadera.","Piernas estiradas y juntas.","S\xfabelas hasta la vertical sin despegar la espalda baja.","B\xe1jalas despacio sin tocar el suelo."],t.s)
B.ayq=s(["Arquear la espalda al bajar."],t.s)
B.ans=new A.co(B.aBO,B.ayq,"Suelta el aire al subir o empujar.")
B.aD4=s(["De rodillas, la rueda bajo los hombros.","Aprieta el abdomen y rueda hacia delante despacio.","Llega tan lejos como puedas sin hundir la espalda.","Vuelve tirando con el abdomen, no con los brazos."],t.s)
B.aFU=s(["Dejar caer la cadera."],t.s)
B.an1=new A.co(B.aD4,B.aFU,"Suelta el aire al subir o empujar.")
B.ayO=s(["Manos algo m\xe1s anchas que los hombros, cuerpo recto.","Baja el pecho hasta casi tocar el suelo.","Codos a unos 45\xb0 del cuerpo.","Empuja hasta estirar los brazos."],t.s)
B.ayA=s(["Hundir la cadera.","Hacer medio recorrido."],t.s)
B.anJ=new A.co(B.ayO,B.ayA,"Suelta el aire al subir o empujar.")
B.aES=s(["Manos juntas bajo el pecho formando un rombo con los dedos.","Cuerpo recto de cabeza a talones.","Baja con los codos pegados al cuerpo.","Empuja con los tr\xedceps."],t.s)
B.I0=s(["Abrir los codos."],t.s)
B.amO=new A.co(B.aES,B.I0,"Suelta el aire al subir o empujar.")
B.avS=s(["Sujeta la pesa pegada al pecho con ambas manos.","Pies algo m\xe1s anchos que la cadera.","Baja entre las piernas con el pecho erguido.","Sube empujando el suelo."],t.s)
B.avG=s(["Inclinarse hacia delante."],t.s)
B.anh=new A.co(B.avS,B.avG,"Suelta el aire al subir o empujar.")
B.aAP=s(["Pies a la anchura de los hombros, brazos al frente.","Cadera atr\xe1s y abajo, pecho arriba.","Baja hasta el paralelo o lo que permita tu movilidad.","Sube apretando gl\xfateos."],t.s)
B.av3=s(["Levantar los talones."],t.s)
B.anG=new A.co(B.aAP,B.av3,"Suelta el aire al subir o empujar.")
B.aBU=s(["De pie, mancuernas delante de los muslos, rodillas apenas flexionadas.","Lleva la cadera atr\xe1s manteniendo la espalda recta.","Baja las pesas pegadas a las piernas hasta sentir los isquios.","Vuelve empujando la cadera adelante."],t.s)
B.auK=s(["Doblar mucho las rodillas (se vuelve sentadilla)."],t.s)
B.amT=new A.co(B.aBU,B.auK,"Suelta el aire al subir o empujar.")
B.aE4=s(["Mancuernas a la altura de los hombros, palmas al frente.","Abdomen firme.","Empuja hacia arriba hasta casi juntarlas.","Baja controlado."],t.s)
B.Hw=s(["Arquear la espalda baja."],t.s)
B.amV=new A.co(B.aE4,B.Hw,"Suelta el aire al subir o empujar.")
B.awO=s(["Mancuernas a los lados, palmas al frente.","Codos fijos.","Sube girando ligeramente la mu\xf1eca hacia fuera.","Baja lento."],t.s)
B.aDH=s(["Balancearse."],t.s)
B.amS=new A.co(B.awO,B.aDH,"Suelta el aire al subir o empujar.")
B.aFN=s(["Sujeta una mancuerna con ambas manos sobre la cabeza.","Baja detr\xe1s de la cabeza doblando solo los codos.","Codos apuntando al techo.","Extiende hasta estirar los brazos."],t.s)
B.anK=new A.co(B.aFN,B.I0,"Suelta el aire al subir o empujar.")
B.aD9=s(["Sentado, piernas estiradas y la banda alrededor de los pies.","Espalda recta y pecho arriba.","Tira llevando los codos atr\xe1s pegados al cuerpo.","Vuelve despacio sin redondear la espalda."],t.s)
B.aw8=s(["Echarse atr\xe1s con el torso."],t.s)
B.anv=new A.co(B.aD9,B.aw8,"Suelta el aire al subir o empujar.")
B.awY=s(["Tumbado boca arriba, rodillas dobladas y pies en el suelo.","Empuja con los talones y sube la cadera.","Arriba, el cuerpo forma una l\xednea de hombros a rodillas.","Aprieta gl\xfateos un segundo y baja."],t.s)
B.HX=s(["Arquear la espalda en vez de usar el gl\xfateo."],t.s)
B.any=new A.co(B.awY,B.HX,"Suelta el aire al subir o empujar.")
B.aAe=s(["De pie en el borde de un escal\xf3n, ap\xf3yate en la pared.","Baja los talones para estirar.","Sube todo lo posible sobre las puntas.","Hazlo lento: aqu\xed la calidad lo es todo."],t.s)
B.aB9=s(["Rebotar."],t.s)
B.ani=new A.co(B.aAe,B.aB9,"Suelta el aire al subir o empujar.")
B.aBk=s(["Tumbado, rodillas dobladas, manos en las sienes.","Despega los hombros del suelo enrollando la columna.","Mira al techo, no tires del cuello.","Baja controlado."],t.s)
B.avV=s(["Tirar de la cabeza con las manos."],t.s)
B.anc=new A.co(B.aBk,B.avV,"Suelta el aire al subir o empujar.")
B.aBG=s(["Rodillas en el suelo (o en un coj\xedn) y manos algo m\xe1s anchas que los hombros.","Cuerpo recto de rodillas a cabeza: no dobles la cadera.","Baja el pecho hasta casi tocar el suelo.","Empuja hasta estirar los brazos."],t.s)
B.aE8=s(["Sacar el trasero hacia arriba.","Bajar solo la cabeza."],t.s)
B.anH=new A.co(B.aBG,B.aE8,"Suelta el aire al subir o empujar.")
B.ax3=s(["Manos en el asiento de una silla firme contra la pared, o en el sof\xe1.","Pies atr\xe1s, cuerpo recto de talones a cabeza.","Baja el pecho hasta el borde del asiento.","Empuja. Cuanto m\xe1s baja la superficie, m\xe1s dif\xedcil."],t.s)
B.aE2=s(["Usar una silla que se desliza.","Hundir la cadera."],t.s)
B.an0=new A.co(B.ax3,B.aE2,"Suelta el aire al subir o empujar.")
B.aAS=s(["Pies sobre una silla o el sof\xe1, manos en el suelo bajo los hombros.","Abdomen y gl\xfateos firmes: el cuerpo es una tabla.","Baja hasta casi tocar el suelo con la frente por delante de las manos.","Empuja hasta estirar los brazos."],t.s)
B.aDe=s(["Dejar caer la cadera.","Abrir los codos en cruz."],t.s)
B.an5=new A.co(B.aAS,B.aDe,"Suelta el aire al subir o empujar.")
B.aBJ=s(["T\xfambate bajo una mesa ROBUSTA y agarra el borde con las dos manos.","Talones apoyados y cadera arriba, en l\xednea con los hombros.","Tira llevando el pecho hacia el borde y los codos hacia el suelo.","Baja despacio hasta estirar los brazos."],t.s)
B.ayc=s(["Usar una mesa ligera o con patas plegables.","Dejar caer la cadera."],t.s)
B.an9=new A.co(B.aBJ,B.ayc,"Suelta el aire al subir el pecho.")
B.aDV=s(["Boca abajo, brazos estirados al frente y piernas juntas.","Mira al suelo para no forzar el cuello.","Despega a la vez brazos, pecho y piernas unos cent\xedmetros.","Aguanta dos segundos arriba y baja con control."],t.s)
B.axa=s(["Levantar la cabeza mirando al frente.","Subir de golpe."],t.s)
B.anu=new A.co(B.aDV,B.axa,"Suelta el aire al subir o empujar.")
B.aFw=s(["Una garrafa de 5 L pesa 5 kg; una mochila con libros, lo que le metas.","Inclina el torso con la espalda recta y apoya la otra mano en una silla.","Tira llevando el codo hacia la cadera.","Baja hasta estirar el brazo y cambia de lado al acabar la serie."],t.s)
B.aFV=s(["Girar el torso para subir.","Asas que se clavan: envu\xe9lvelas en una toalla."],t.s)
B.anp=new A.co(B.aFw,B.aFV,"Suelta el aire al subir o empujar.")
B.avP=s(["Forma una V invertida: cadera arriba, manos y pies en el suelo.","Acerca los pies a las manos todo lo que te permita la flexibilidad.","Baja la cabeza hacia el suelo, por delante de las manos.","Empuja hasta estirar los brazos. Es un press de hombro sin pesas."],t.s)
B.aC2=s(["Bajar la cadera y convertirla en una flexi\xf3n normal."],t.s)
B.anx=new A.co(B.avP,B.aC2,"Suelta el aire al subir o empujar.")
B.aBo=s(["Pisa la banda con los dos pies y agarra los extremos a la altura de los hombros.","Abdomen firme y gl\xfateos apretados.","Empuja hacia arriba hasta estirar los brazos.","Baja despacio: la banda tira, no la dejes ganar."],t.s)
B.amQ=new A.co(B.aBo,B.Hw,"Suelta el aire al subir o empujar.")
B.aEe=s(["Una botella de agua en cada mano (1,5 L \u2248 1,5 kg).","Codos un poco doblados y hombros lejos de las orejas.",u.Y,"Baja en tres segundos."],t.s)
B.axI=s(["Balancear el cuerpo.","Subir m\xe1s arriba de los hombros."],t.s)
B.anL=new A.co(B.aEe,B.axI,"Suelta el aire al subir o empujar.")
B.aGd=s(["Pisa la banda con los pies a la anchura de la cadera.","Codos pegados al cuerpo y quietos.","Sube doblando solo los codos.","Baja despacio hasta estirar."],t.s)
B.av4=s(["Adelantar los codos.","Echarse atr\xe1s para ayudarse."],t.s)
B.amY=new A.co(B.aGd,B.av4,"Suelta el aire al subir o empujar.")
B.aGc=s(["Agarra la garrafa por el asa con el brazo estirado.","Codo pegado al costado.","Sube doblando el codo hasta el hombro.","Baja lento. Cambia de mano en cada serie."],t.s)
B.ayr=s(["Balancear el torso."],t.s)
B.anw=new A.co(B.aGc,B.ayr,"Suelta el aire al subir o empujar.")
B.az3=s(["Silla firme contra la pared. Manos en el borde del asiento, dedos al frente.","Piernas estiradas (m\xe1s dif\xedcil) o dobladas (m\xe1s f\xe1cil).","Baja doblando los codos hacia atr\xe1s hasta unos 90\xb0.","Empuja hasta estirar los brazos."],t.s)
B.axy=s(["Bajar demasiado si te molesta el hombro.","Abrir los codos hacia fuera."],t.s)
B.ant=new A.co(B.az3,B.axy,"Suelta el aire al subir o empujar.")
B.aCC=s(["Sentado, antebrazo sobre el muslo y la mu\xf1eca por fuera de la rodilla.","Deja que la garrafa baje con la mu\xf1eca.","Sube doblando solo la mu\xf1eca.","Recorridos cortos y lentos."],t.s)
B.av6=s(["Mover el antebrazo."],t.s)
B.ana=new A.co(B.aCC,B.av6,"Suelta el aire al subir o empujar.")
B.aEB=s(["Una garrafa o mochila pesada en cada mano.","Hombros atr\xe1s y abajo, pecho arriba, abdomen firme.","Camina por la casa (o marcha en el sitio) a pasos cortos.","Aprieta las asas durante todo el tiempo marcado."],t.s)
B.ax1=s(["Encorvarse hacia delante.","Inclinarse hacia un lado."],t.s)
B.amR=new A.co(B.aEB,B.ax1,"Respira corto y constante mientras caminas.")
B.aEI=s(["Posici\xf3n de flexi\xf3n, manos bajo los hombros.","Lleva una rodilla hacia el pecho y vuelve.","Alterna las piernas a buen ritmo sin subir la cadera.","Cada rodilla que llega al pecho cuenta como una repetici\xf3n."],t.s)
B.aBr=s(["Levantar la cadera.","Rebotar con los hombros."],t.s)
B.ang=new A.co(B.aEI,B.aBr,"Respira r\xedtmico, sin aguantar el aire.")
B.aDI=s(["Boca arriba, manos bajo la cadera y la espalda baja pegada al suelo.","Piernas estiradas y algo despegadas del suelo.","Sube y baja las piernas alternando, como unas tijeras.","Movimientos cortos y controlados."],t.s)
B.azF=s(["Despegar la espalda baja del suelo."],t.s)
B.amW=new A.co(B.aDI,B.azF,"Suelta el aire al subir o empujar.")
B.azx=s(["De pie, manos en la cintura.","Da un paso largo hacia atr\xe1s.",u.B,"Vuelve empujando con el pie de delante."],t.s)
B.atp=s(["Dejar que la rodilla de delante se vaya hacia dentro."],t.s)
B.ano=new A.co(B.azx,B.atp,"Suelta el aire al subir o empujar.")
B.au6=s(["De espaldas a una silla firme, apoya el empeine de un pie en el asiento.","El pie de delante, a un paso largo de la silla.","Baja recto hasta que el muslo de delante quede casi paralelo.","Sube empujando con el tal\xf3n de delante."],t.s)
B.axR=s(["Pie de delante demasiado cerca de la silla.","Inclinarse hacia un lado."],t.s)
B.an2=new A.co(B.au6,B.axR,"Suelta el aire al subir o empujar.")
B.aCJ=s(["Espalda pegada a la pared, pies un paso por delante.","Baja hasta que los muslos queden paralelos al suelo.","Rodillas sobre los tobillos, no por delante.","Aguanta el tiempo marcado."],t.s)
B.avT=s(["Apoyar las manos en las piernas para descargar."],t.s)
B.anb=new A.co(B.aCJ,B.avT,"Respira lento; no aguantes el aire.")
B.ays=s(["Usa un escal\xf3n o un caj\xf3n estable, nunca una silla con ruedas.","Apoya el pie entero arriba.","Sube empujando solo con esa pierna y eleva la otra rodilla.","Baja despacio. Repite y cambia de lado."],t.s)
B.aue=s(["Impulsarse con la pierna de abajo."],t.s)
B.anj=new A.co(B.ays,B.aue,"Suelta el aire al subir o empujar.")
B.atj=s(["Pies a la anchura de los hombros.","Baja a una sentadilla con los brazos atr\xe1s.","Salta lanzando los brazos arriba.","Aterriza suave, sobre la punta y luego el tal\xf3n, ya bajando a la siguiente."],t.s)
B.aAC=s(["Caer con las rodillas r\xedgidas.","Rodillas hacia dentro al aterrizar."],t.s)
B.amP=new A.co(B.atj,B.aAC,"Suelta el aire al saltar.")
B.ayY=s(["Boca arriba, un pie en el suelo y la otra pierna estirada al aire.","Empuja con el tal\xf3n y sube la cadera.","Arriba, cadera recta: que no se caiga hacia un lado.","Baja despacio. Cambia de pierna."],t.s)
B.amX=new A.co(B.ayY,B.HX,"Suelta el aire al subir o empujar.")
B.aAz=s(["Punta de un pie en el borde de un escal\xf3n; ap\xf3yate en la pared.","Baja el tal\xf3n hasta estirar.","Sube todo lo que puedas sobre la punta.","Lento arriba y abajo. Cambia de pierna."],t.s)
B.aD5=s(["Rebotar abajo."],t.s)
B.anD=new A.co(B.aAz,B.aD5,"Suelta el aire al subir o empujar.")
B.aBR=s(["De pie, rodillas casi estiradas y manos como si sujetaras una comba.","Salta solo con los tobillos, a pocos cent\xedmetros del suelo.","Aterriza sobre la punta, sin apoyar el tal\xf3n.","Cuenta los saltos o hazlos por tiempo."],t.s)
B.aBM=s(["Doblar mucho las rodillas.","Hacer ruido al caer: aterriza suave."],t.s)
B.an7=new A.co(B.aBR,B.aBM,"Respira r\xedtmico.")
B.atW=s(["De pie, pies juntos y brazos a los lados.","Salta abriendo las piernas y subiendo los brazos por encima de la cabeza.","Salta de nuevo para volver a cerrar.","Mant\xe9n un ritmo que puedas sostener."],t.s)
B.atk=s(["Aterrizar sobre los talones."],t.s)
B.ane=new A.co(B.atW,B.atk,"Respira r\xedtmico, sin aguantar el aire.")
